  'help.faq.cantLogin.a': 'Düzgün email və şifrə istifadə etdiyinə əmin ol. Şifrəni unutmusansa, giriş ekranında "Şifrəni unutmusan?" düyməsini bas. Problemin davam edərsə, dəstək bileti yarat.',
  'help.faq.notReceiving.q': 'Email almıram',
  'help.faq.notReceiving.a': 'Əvvəlcə Spam qovluğunu yoxla. Saxlama yerinin dolu olmadığından əmin ol. Problemin davam edərsə, göndərənin düzgün email ünvanına malik olduğunu təsdiq et və bilet yarat.',
  'help.faq.cantSend.q': 'Email göndərə bilmirəm',
  'help.faq.cantSend.a': 'İnternet bağlantını və alıcının email ünvanını yoxla. Əlavələrin 25MB-dan çox olmadığını təsdiq et. Bir neçə dəqiqədən sonra yenidən cəhd et.',
