  'help.faq.appAccess.a': 'Chatyy-yə chatyy.com.br saytından brauzer vasitəsilə daxil ola bilərsən, ya da cihazının tətbiq mağazasından tətbiqi yükləyə bilərsən.',
  'privacy.title': 'Məxfilik Siyasəti',
  'privacy.subtitle': 'Məlumatlarını necə qoruyuruq və emal edirik',
  'privacy.lastUpdated': 'Son yeniləmə: Mart 2026',
  'privacy.dataCollection.title': 'Məlumatların Toplanması',
  'privacy.dataCollection.body': 'Yalnız email xidməti üçün lazım olan məlumatları toplayırıq: adın, email ünvanın və göndərilən və alınan mesajların məzmunu. Şəxsi məlumatlarını üçüncü tərəflərlə marketinq məqsədilə satmırıq və paylaşmırıq.',
  'privacy.dataUsage.title': 'Məlumatlarını Necə İstifadə Edirik',
  'privacy.dataUsage.body': 'Məlumatların yalnız email xidmətini işlətmək və yaxşılaşdırmaq üçün istifadə olunur, o cümlədən mesajların çatdırılması, spamın filtr edilməsi, AI funksiyaları (sənin razılığınla) və hesabın təhlükəsizliyi.',
  'privacy.dataSecurity.title': 'Məlumatların Təhlükəsizliyi',
  'privacy.dataSecurity.body': 'Bütün məlumatların ötürülməsi və saxlanması üçün sənaye standartı şifrələmə (TLS/SSL) istifadə edirik. Sessiyalar şifrələnmiş tokenlərlə və CSRF qoruması ilə qorunur. Təhlükəsizlik praktikalarımızı mütəmadi olaraq yoxlayırıq.',
  'privacy.cookies.title': 'Cookies və Yerli Saxlama',
  'privacy.cookies.body': 'Sessiyanı saxlamaq, seçimlərini (mövzu, dil) xatırlamaq və axıcı bir təcrübə təmin etmək üçün zəruri cookies və yerli saxlamadan istifadə edirik. Üçüncü tərəf izləmə cookies istifadə etmirik.',
  'privacy.thirdParties.title': 'Üçüncü Tərəf Xidmətləri',
  'privacy.thirdParties.body': 'AI (Anthropic Claude) və push bildirişləri kimi spesifik funksiyalar üçün üçüncü tərəf xidmətlərindən istifadə edə bilərik. Bu xidmətlər öz məxfilik siyasətlərinə riayət edir və yalnız minimum lazım olan məlumatları emal edir.',
  'privacy.rights.title': 'Sənin Hüquqların',
  'privacy.rights.body': 'İstədiyin zaman şəxsi məlumatlarına daxil olmaq, düzəltmək, ixrac etmək və ya silmək hüququna maliksən. Məlumatlarını Tənzimləmələrdə idarə edə bilərsən və ya dəstək ilə əlaqə saxlaya bilərsən.',
  'privacy.contact.title': 'Bizimlə Əlaqə',
  'privacy.contact.body': 'Məxfilik məsələləri və ya məlumat sorğuları üçün privacy@chatyy.com.br ünvanı ilə əlaqə saxla. 30 gün ərzində cavab verəcəyik.',
  'terms.title': 'Xidmət Şərtləri',
  'terms.subtitle': 'Chatyy istifadə qaydaları',
  'terms.lastUpdated': 'Son yeniləmə: Mart 2026',
  'terms.acceptance.title': 'Şərtlərin Qəbul Edilməsi',
  'terms.acceptance.body': 'Chatyy-yə daxil olduqda və ya istifadə etdikdə, bu Xidmət Şərtləri ilə razılaşırsan. Bu şərtlərin hər hansı bir hissəsi ilə razı deyilsə, xidmətdən istifadə etmə.',
  'terms.services.title': 'Xidmətlərin Təsviri',
  'terms.services.body': 'Chatyy email xidməti təqdim edir, o cümlədən email göndərmə, qəbul etmə və idarə etmə, eləcə də AI funksiyaları, təqvim inteqrasiyası və video konfrans.',
  'terms.accounts.title': 'İstifadəçi Hesabları',
  'terms.accounts.body': 'Sənin şifrələrinin təhlükəsizliyini təmin etmək sənin məsuliyyətindir. Şifrəni paylaşma və ya hesabına icazəsiz girişə imkan vermə. Bu xidmətdən istifadə etmək üçün ən azı 13 yaşında olmalısan.',
  'terms.conduct.title': 'Qəbul Edilən İstifadə',
  'terms.conduct.body': 'Xidməti spam, zərərli proqram, phishing və ya hər hansı qanunsuz məzmun göndərmək üçün istifadə etməməyi qəbul edirsən. Başqa istifadəçilərin hesablarına daxil olmağa və ya xidmətin infrastrukturunu pozmağa çalışmayın.',
  'terms.content.title': 'Məzmunun Mülkiyyəti',
  'terms.content.body': 'Xidmət vasitəsilə yaratdığın və göndərdiyin bütün məzmunun mülkiyyətini saxlayırsan. Sənin email və əlavələrin üzərində mülkiyyət iddia etmirik. Xidməti təmin etmək üçün lazım olduqda məzmunu emal edə bilərik.',
  'terms.limitation.title': 'Məsuliyyətin Məhdudlaşdırılması',
  'terms.limitation.body': 'Chatyy "olduğu kimi" təqdim edilir. 99,9% mövcudluğu təmin etməyə çalışırıq, amma kesintisiz xidmət zəmanəti vermirik. Xidmətin istifadəsindən irəli gələn dolayı, təsadüfi və ya nəticəvi zərərlərə görə məsuliyyət daşımırıq.',
  'terms.termination.title': 'Hesabın Bağlanması',
  'terms.termination.body': 'Bu şərtləri pozan hesabları dayandıra və ya bağlaya bilərik. İstədiyin zaman Tənzimləmələrdə hesabını silə bilərsən. Bağlandıqdan sonra məlumatların 30 gün ərzində silinəcək.',
  'terms.changes.title': 'Şərtlərdə Dəyişikliklər',
  'terms.changes.body': 'Bu şərtləri dövri olaraq yeniləyə bilərik. Əhəmiyyətli dəyişikliklər barədə email və ya tətbiqdə bildiriş ilə məlumat verəcəyik. Dəyişikliklərdən sonra davamlı istifadə şərtlərin yenilənmiş olduğunu qəbul edir.',
